from collections import deque


def topological_order(nodes, edges):
    """Return a list of all nodes such that for every edge (a, b), a precedes b.

    Raises ValueError if the graph has a cycle (including self-loops).
    Inputs are not mutated. Runs in O(V + E) time and space.
    """
    nodes = list(nodes)
    successors = {n: set() for n in nodes}  # set dedups repeated edges
    indegree = {n: 0 for n in nodes}
    for a, b in edges:
        if b not in successors[a]:
            successors[a].add(b)
            indegree[b] += 1

    queue = deque(n for n in nodes if indegree[n] == 0)
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for m in successors[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                queue.append(m)

    if len(order) != len(nodes):
        raise ValueError("graph contains a cycle")
    return order
