    unique_edges = set(edges)
    adj = {n: [] for n in nodes}
    indegree = {n: 0 for n in nodes}
    for a, b in unique_edges:
        if a == b:
            raise ValueError("cycle detected: self-loop on %r" % (a,))
        adj[a].append(b)
        indegree[b] += 1

    queue = deque(n for n in nodes if indegree[n] == 0)
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for m in adj[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                queue.append(m)

    if len(order) != len(nodes):
        raise ValueError("cycle detected")
    return order

