    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for m in successors[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                queue.append(m)

    if len(order) != len(indegree):
        raise ValueError("graph contains a cycle")
    return order

