import sqlite3

MIN_LIMIT = 1
MAX_LIMIT = 100


def _escape_like(text, escape="\\"):
    """Escape LIKE wildcards so text matches literally."""
    return (
        text.replace(escape, escape + escape)
        .replace("%", escape + "%")
        .replace("_", escape + "_")
    )


def search(conn, name_prefix, limit):
    if not isinstance(name_prefix, str):
        raise ValueError("name_prefix must be a string")
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise ValueError("limit must be an integer")
    limit = max(MIN_LIMIT, min(MAX_LIMIT, limit))

    pattern = _escape_like(name_prefix) + "%"
    return conn.execute(
        "SELECT id, name FROM users WHERE name LIKE ? ESCAPE '\\' "
        "ORDER BY name, id LIMIT ?",
        (pattern, limit),
    ).fetchall()
