import csv
import io

_DIGITS = frozenset("0123456789")


def _parse_age(value):
    if not value or not set(value) <= _DIGITS:
        raise ValueError(f"invalid age: {value!r}")
    # Strip leading zeros first so very long digit strings can't hit int() limits.
    age = int(value.lstrip("0") or "0") if len(value) < 100 else None
    if age is None or age > 130:
        raise ValueError(f"age out of range: {value[:20]!r}")
    return age


def read_people(text):
    """Parse CSV text with header name,age into a list of dicts."""
    reader = csv.reader(io.StringIO(text, newline=""), strict=True)
    try:
        header = next(reader, None)
        if header != ["name", "age"]:
            raise ValueError(f"invalid header: {header!r}")
        people = []
        for row in reader:
            if len(row) != 2:
                raise ValueError(f"expected 2 columns, got {len(row)}: {row!r}")
            people.append({"name": row[0], "age": _parse_age(row[1])})
    except csv.Error as e:
        raise ValueError(f"invalid CSV: {e}") from e
    return people
