import re

_AGE_RE = re.compile(r"[0-9]+")


def _parse_csv(text):
    """Strict RFC 4180-style parser (also accepts bare \\n or \\r as row ends)."""
    rows = []
    fields = []
    buf = []
    state = "start"  # start | plain | quoted | after_quote
    pending = False  # a record has begun
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        i += 1
        if state == "quoted":
            if c == '"':
                state = "after_quote"
            else:
                buf.append(c)
            continue
        if state == "after_quote" and c == '"':
            buf.append('"')
            state = "quoted"
            continue
        if c in "\r\n":
            if c == "\r" and text[i : i + 1] == "\n":
                i += 1
            fields.append("".join(buf))
            rows.append(fields)
            fields, buf, state, pending = [], [], "start", False
            continue
        pending = True
        if c == ",":
            fields.append("".join(buf))
            buf, state = [], "start"
        elif state == "after_quote":
            raise ValueError("invalid CSV: data after closing quote")
        elif c == '"':
            if state != "start":
                raise ValueError("invalid CSV: quote inside unquoted field")
            state = "quoted"
        else:
            buf.append(c)
            state = "plain"
    if state == "quoted":
        raise ValueError("invalid CSV: unterminated quoted field")
    if pending:
        fields.append("".join(buf))
        rows.append(fields)
    return rows


def read_people(text):
    """Parse CSV text with header name,age into a list of dicts."""
    if not isinstance(text, str):
        raise ValueError("text must be a str")
    rows = _parse_csv(text)
    if not rows or rows[0] != ["name", "age"]:
        raise ValueError("invalid header")
    people = []
    for row in rows[1:]:
        if len(row) != 2:
            raise ValueError(f"expected 2 columns, got {len(row)}: {row!r}")
        name, age_text = row
        if not _AGE_RE.fullmatch(age_text):
            raise ValueError(f"invalid age: {age_text!r}")
        age = int(age_text)
        if age > 130:
            raise ValueError(f"age out of range: {age}")
        people.append({"name": name, "age": age})
    return people
