async function collectPages(fetchPage) {
  const items = [];
  const seen = new Set();
  let cursor = null;
  for (;;) {
    if (cursor !== null) {
      if (seen.has(cursor)) {
        throw new Error(`Repeated cursor: ${JSON.stringify(cursor)}`);
      }
      seen.add(cursor);
    }
    const page = await fetchPage(cursor);
    for (const item of page.items) items.push(item);
    if (page.next === null) return items;
    cursor = page.next;
  }
}

module.exports = { collectPages };
