'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

// Deep-copies a JSON-like value, rejecting unsafe own keys at any depth.
function cloneValue(value) {
  if (Array.isArray(value)) return value.map(cloneValue);
  if (isPlainObject(value)) {
    const out = {};
    for (const key of Object.keys(value)) {
      if (UNSAFE_KEYS.has(key)) throw new TypeError(`Unsafe key: ${key}`);
      out[key] = cloneValue(value[key]);
    }
    return out;
  }
  if (value !== null && (typeof value === 'object' || typeof value === 'function')) {
    throw new TypeError('Unsupported value: expected JSON-like data');
  }
  return value;
}

// Merges two already-cloned values; the pieces are private so they can be reused.
function mergeCloned(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return override;
  for (const key of Object.keys(override)) {
    base[key] = Object.prototype.hasOwnProperty.call(base, key)
      ? mergeCloned(base[key], override[key])
      : override[key];
  }
  return base;
}

function mergeConfig(base, override) {
  // Clone both fully first so unsafe keys are rejected even in discarded parts.
  return mergeCloned(cloneValue(base), cloneValue(override));
}

module.exports = { mergeConfig };
