  if (value === null || typeof value !== 'object') {
    if (typeof value === 'function' || typeof value === 'symbol' || typeof value === 'bigint') {
      throw new TypeError(`Unsupported value at ${path}`);
    }
    return;
  }
  if (!Array.isArray(value) && !isPlainObject(value)) {
    throw new TypeError(`Unsupported value at ${path}`);
  }
  if (stack.has(value)) throw new TypeError(`Circular reference at ${path}`);
  stack.add(value);
  if (Array.isArray(value)) {
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) throw new Error(`Unsafe key "${key}" at ${path}`);
    }
    value.forEach((item, i) => validate(item, `${path}[${i}]`, stack));
  } else {
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) throw new Error(`Unsafe key "${key}" at ${path}`);
      validate(value[key], `${path}.${key}`, stack);
    }
  }
  stack.delete(value);
}

// Assumes validated input.
function clone(value) {
  if (Array.isArray(value)) return value.map(clone);
  if (isPlainObject(value)) {
    const out = {};
    for (const key of Object.keys(value)) out[key] = clone(value[key]);
    return out;
  }
  return value;
}

function merge(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return clone(override);
  const out = {};
  for (const key of Object.keys(base)) {
    out[key] = Object.prototype.hasOwnProperty.call(override, key)
      ? merge(base[key], override[key])
      : clone(base[key]);
  }
  for (const key of Object.keys(override)) {
    if (!Object.prototype.hasOwnProperty.call(base, key)) out[key] = clone(override[key]);
  }
  return out;
}

