'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

// Validates a whole input tree and rejects unsafe keys at any depth,
// including inside arrays. Also rejects cycles and non-JSON-like values.
function validate(value, path, stack) {
  if (value === null || typeof value !== 'object') {
    if (typeof value === 'function' || typeof value === 'symbol') {
      throw new TypeError(`Unsupported value at ${path}`);
    }
    return;
  }
  const isArr = Array.isArray(value);
  if (!isArr && !isPlainObject(value)) {
    throw new TypeError(`Unsupported object at ${path}`);
  }
  if (stack.has(value)) throw new TypeError(`Circular reference at ${path}`);
  stack.add(value);
  if (isArr) {
    for (let i = 0; i < value.length; i++) validate(value[i], `${path}[${i}]`, stack);
  } else {
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) {
        throw new Error(`Unsafe key "${key}" at ${path}`);
      }
      validate(value[key], `${path}.${key}`, stack);
    }
  }
  stack.delete(value);
}

function clone(value) {
  if (Array.isArray(value)) return Array.from(value, clone);
  if (isPlainObject(value)) {
    const out = {};
    for (const key of Object.keys(value)) out[key] = clone(value[key]);
    return out;
  }
  return value;
}

function merge(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return clone(override);
  const out = {};
  for (const key of Object.keys(base)) {
    if (!Object.prototype.hasOwnProperty.call(override, key)) out[key] = clone(base[key]);
  }
  for (const key of Object.keys(override)) {
    out[key] = Object.prototype.hasOwnProperty.call(base, key)
      ? merge(base[key], override[key])
      : clone(override[key]);
  }
  return out;
}

function mergeConfig(base, override) {
  validate(base, 'base', new Set());
  validate(override, 'override', new Set());
  return merge(base, override);
}

module.exports = { mergeConfig };
