    const product = total * w;
    if (!Number.isSafeInteger(product)) throw new RangeError('total * weight is not a safe integer');
    const rem = product % sum;
    result.push((product - rem) / sum);
    rems.push(rem);
    allocated += result[i];
  });

  const order = weights.map((_, i) => i).sort((a, b) => rems[b] - rems[a] || a - b);
  for (let k = 0; k < total - allocated; k++) result[order[k]] += 1;
  return result;
}

