    // Correct any floating-point error in the division so the floor is exact.
    let rem = product - share * sum;
    let s = share;
    if (rem < 0) { s -= 1; rem += sum; }
    else if (rem >= sum) { s += 1; rem -= sum; }
    shares.push(s);
    remainders.push(rem);
    allocated += s;
  }

