from datetime import datetime, timezone


def utc_day_start(text):
    """Return UTC midnight of the UTC day containing the ISO 8601 instant `text`."""
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    s = text.strip()
    if s[-1:] in ("Z", "z"):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)  # raises ValueError on invalid input
