import re
from datetime import datetime, timezone

_TZ_RE = re.compile(r"([+-])(\d{2})(?::?(\d{2}))?$")


def utc_day_start(text):
    """Return UTC midnight of the UTC day containing the instant `text`."""
    if not isinstance(text, str):
        raise ValueError("timestamp must be a string")
    s = text.strip()
    if s[-1:] in ("Z", "z"):
        s = s[:-1] + "+00:00"
    else:
        # Normalize +HH and +HHMM to +HH:MM (fromisoformat on older Pythons).
        m = _TZ_RE.search(s)
        if m and "T" in s[: m.start()]:
            s = s[: m.start()] + "%s%s:%s" % (m.group(1), m.group(2), m.group(3) or "00")
    dt = datetime.fromisoformat(s)  # raises ValueError on invalid input
    if dt.tzinfo is None or dt.utcoffset() is None:
        raise ValueError("timestamp must include an explicit UTC offset")
    utc = dt.astimezone(timezone.utc)
    return utc.replace(hour=0, minute=0, second=0, microsecond=0)
