const VERSION_RE = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/;

function compareVersion(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') {
    throw new TypeError('versions must be strings');
  }
  const ma = VERSION_RE.exec(a);
  const mb = VERSION_RE.exec(b);
  if (!ma || !mb) throw new TypeError('malformed version string');
  for (let i = 1; i <= 3; i++) {
