'use strict';

class Emitter {
  constructor() {
    this._events = new Map(); // event -> Map(fn -> registration)
  }

  on(event, fn) {
    let listeners = this._events.get(event);
    if (!listeners) {
      listeners = new Map();
      this._events.set(event, listeners);
    }
    let reg = listeners.get(fn);
    if (!reg) {
      reg = { fn };
      listeners.set(fn, reg);
    }
    // A stale unsubscribe must not remove a later re-registration.
    return () => {
      const current = this._events.get(event);
      if (current && current.get(fn) === reg) this.off(event, fn);
    };
  }

  off(event, fn) {
    const listeners = this._events.get(event);
    if (!listeners) return;
    listeners.delete(fn);
    if (listeners.size === 0) this._events.delete(event);
  }

  emit(event, value) {
    const listeners = this._events.get(event);
    if (!listeners) return;
    for (const fn of Array.from(listeners.keys())) fn(value);
  }
}

module.exports = { Emitter };
