export type Result<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: string };

export function mapResult<T, U>(r: Result<T>, fn: (value: T) => U): Result<U> {
  if (!r.ok) {
    return r;
  }
  return { ok: true, value: fn(r.value) };
}

export function unwrapOr<T>(r: Result<T>, fallback: T): T {
  return r.ok ? r.value : fallback;
}

// Examples (type-checked under strict mode).
const parsed: Result<string> = { ok: true, value: "42" };
export const exampleLength: Result<number> = mapResult(parsed, (s) => s.length);
export const exampleFailure: Result<number> = mapResult<string, number>(
  { ok: false, error: "bad input" },
  (s) => s.length,
);
export const exampleValue: number = unwrapOr(exampleFailure, 0);

import { test } from "node:test";
import assert from "node:assert/strict";
import { mapResult, unwrapOr, type Result } from "../src/solution.ts";

test("mapResult applies fn on success", () => {
  const r: Result<number> = { ok: true, value: 2 };
  assert.deepEqual(mapResult(r, (n) => String(n * 2)), { ok: true, value: "4" });
});

test("mapResult does not call fn on failure and returns it unchanged", () => {
  let calls = 0;
  const r: Result<number> = { ok: false, error: "boom" };
  const out = mapResult(r, (n) => {
    calls++;
    return n + 1;
  });
  assert.equal(calls, 0);
  assert.deepEqual(out, { ok: false, error: "boom" });
});

test("mapResult lets fn exceptions propagate", () => {
  const r: Result<number> = { ok: true, value: 1 };
  assert.throws(
    () =>
      mapResult(r, () => {
        throw new Error("fn failed");
      }),
    /fn failed/,
  );
});

test("unwrapOr returns value on success and fallback on failure", () => {
  assert.equal(unwrapOr({ ok: true, value: 5 }, 0), 5);
  assert.equal(unwrapOr<number>({ ok: false, error: "x" }, 7), 7);
});

