export type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function mapResult<T, U>(r: Result<T>, fn: (value: T) => U): Result<U> {
  if (!r.ok) {
    return r;
  }
  return { ok: true, value: fn(r.value) };
}

export function unwrapOr<T>(r: Result<T>, fallback: T): T {
  return r.ok ? r.value : fallback;
}

import assert from "node:assert/strict";
import { Result, mapResult, unwrapOr } from "./solution";

// Examples (type-checked)
const good: Result<number> = { ok: true, value: 21 };
const bad: Result<number> = { ok: false, error: "boom" };

const doubled: Result<number> = mapResult(good, (n) => n * 2);
const asText: Result<string> = mapResult(good, (n) => `n=${n}`);
const n: number = unwrapOr(bad, 0);

assert.deepEqual(doubled, { ok: true, value: 42 });
assert.deepEqual(asText, { ok: true, value: "n=21" });
assert.equal(n, 0);
assert.equal(unwrapOr(good, 0), 21);

// fn is not called on failure, and the failure is returned unchanged
let calls = 0;
const mapped = mapResult(bad, (x) => {
  calls++;
  return String(x);
});
assert.equal(calls, 0);
assert.equal(mapped, bad);
assert.deepEqual(mapped, { ok: false, error: "boom" });

// fn is called exactly once on success
mapResult(good, (x) => {
  calls++;
  return x;
});
assert.equal(calls, 1);

// Exceptions from fn propagate
assert.throws(
  () =>
    mapResult(good, () => {
      throw new Error("fn failed");
    }),
  /fn failed/,
);

console.log("all tests passed");

